function Store({children}){const [cart,setCart]=useState(()=>JSON.parse(localStorage.getItem('eb-cart')||'[]'));const [wish,setWish]=useState(()=>JSON.parse(localStorage.getItem('eb-wish')||'[]'));const [city,setCity]=useState(()=>{const saved=localStorage.getItem('eb-city');return (saved&&['Faridabad'].includes(saved))?saved:'Faridabad';});useEffect(()=>localStorage.setItem('eb-cart',JSON.stringify(cart)),[cart]);useEffect(()=>localStorage.setItem('eb-wish',JSON.stringify(wish)),[wish]);useEffect(()=>localStorage.setItem('eb-city',city),[city]);const add=p=>setCart(c=>[...c,p]);const toggle=p=>setWish(w=>w.some(x=>x.id===p.id)?w.filter(x=>x.id!==p.id):[...w,p]);return <AppContext.Provider value={{cart,setCart,wish,toggle,add,city,setCity}}>{children}</AppContext.Provider>}
