  if(meta&&!term)return <CategoryPage meta={meta} slug={slug}/>;
  const categoryPage=birthdayPages.find(page=>page.path.split('/').pop()===slug)||balloonPages.find(page=>page.path.split('/').pop()===slug)||occasionPages.find(page=>page.path.split('/').pop()===slug)||morePages.find(page=>page.slug===slug);
  if(!term&&!categoryPage)return <NotFoundPage/>;
