  const description=term?'Search decoration designs from Surprised balloon decoration.':`${categoryPage.title} in Faridabad by Surprised balloon decoration. Browse designs and contact us to discuss event details and availability.`;
  const canonical=DOMAIN+loc.pathname;
  let shown=term?allRealProducts.filter(p=>p.title.toLowerCase().includes(term.toLowerCase())):categoryPage.items;
  shown=[...shown].sort((a,b)=>sort==='Price Low to High'?a.price-b.price:sort==='Price High to Low'?b.price-a.price:sort==='Highest Rated'?b.rating-a.rating:0);
  const related=[...birthdayPages,...balloonPages,...occasionPages].filter(page=>page.path!==loc.pathname).slice(0,4);
